// Arma el aviso con el/los código(s) de seguimiento. Escapa todo lo que viene del formulario.
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
return $input.all().map(({ json }) => {
  const d = json.body.data;
  const resend = d.reason === "resend";
  const rows = d.applications.map((a) =>
    '<tr><td style="padding:8px 12px;font:600 18px monospace;letter-spacing:1px">' + esc(a.trackingCode) + '</td>' +
    '<td style="padding:8px 12px">' + esc(a.studentFirstName) + ' · ' + esc(a.grade) + ' · ' + esc(a.academicYear) + '</td>' +
    '<td style="padding:8px 12px">' + esc(a.status) + '</td></tr>').join("");
  const statusUrl = d.statusUrl; // la app manda el enlace completo (n8n Cloud no expone variables de entorno)
  const html =
    '<div style="font-family:system-ui,sans-serif;color:#0F1E2E;max-width:560px">' +
    '<h2 style="color:#0E6E8C">' + esc(d.institution.name) + '</h2>' +
    '<p>Hola ' + esc(d.guardian.name) + ',</p>' +
    '<p>' + (resend ? 'Recibimos un pedido para recordar tus códigos de seguimiento.' : 'Recibimos tu solicitud de admisión. Este es tu código de seguimiento:') + '</p>' +
    '<table style="border-collapse:collapse;background:#EAF0F4;border-radius:8px">' + rows + '</table>' +
    '<p>Para consultar el estado ingresa a <a href="' + esc(statusUrl) + '">' + esc(statusUrl) + '</a> con el código y la cédula del representante.</p>' +
    (resend ? '<p style="color:#4A5B6C;font-size:13px">Si no pediste este correo, puedes ignorarlo: nadie puede ver tu solicitud sin tu cédula.</p>' : '') +
    '<p style="color:#4A5B6C;font-size:13px">Dudas: ' + esc(d.institution.email) + ' · ' + esc(d.institution.phone) + '</p></div>';
  const codes = d.applications.map((a) => a.trackingCode).join(", ");
  return { json: {
    to: d.guardian.email,
    // WhatsApp Cloud API: solo dígitos con código de país (Ecuador: 09XXXXXXXX → 5939XXXXXXXX).
    phone: (() => { const p = String(d.guardian.phone ?? "").replace(/\D/g, ""); return !p ? null : p.length === 10 && p.startsWith("0") ? "593" + p.slice(1) : p; })(),
    subject: (resend ? "Tus códigos de seguimiento · " : "Solicitud recibida · ") + d.institution.name,
    html,
    whatsappText: (resend ? "Tus códigos de seguimiento: " : "Recibimos tu solicitud. Tu código de seguimiento es ") + codes + ". Consulta el estado en " + statusUrl,
  } };
});
